const sourceCard = (asset, active) => `<button class="animation-source-card ${active ? "active" : ""}" type="button" data-animation-source="${asset.id}"><span><img src="${fileOf(asset)}" alt=""/></span><b>${escape(asset.name)}</b><small>${escape(asset.kind || "asset")}</small></button>`;
const motionCard = (id, motion, active) => `<button class="animation-motion-card ${active ? "active" : ""}" type="button" data-animation-motion="${id}"><i>${motion.icon}</i><b>${motion.title}</b><small>${motion.hint}</small></button>`;
const frameImage = (frame) => fileOf(frame.asset);
const frameCard = (frame) => `<div class="animation-frame-card ${frame.status} ${frame.isLocked ? "locked" : ""}" data-animation-frame="${frame.id}"><span class="animation-frame-number">${frame.position + 1}</span>${frame.role === "keyframe" ? `<span class="animation-frame-lock">◆</span>` : ""}<div class="animation-frame-visual">${frameImage(frame) ? `<img src="${frameImage(frame)}" alt="Frame ${frame.position + 1}"/>` : frame.status === "running" ? `<span class="animation-spinner" aria-label="Generating"></span>` : `<i>+</i>`}</div><b>${frame.role === "keyframe" ? "Keyframe" : statusLabel(frame)}</b>${frame.position > 0 && frame.status === "succeeded" && !frame.isLocked ? `<button type="button" data-animation-regenerate="${frame.id}" data-animation-clip="${frame.clip_id}">Regenerate</button>` : ""}</div>`;
