  const syncCost = () => { const count = Number(form.elements.frameCount.value); const sequential = TEMPORAL_EDIT_MOTIONS.has(motion); root.querySelector("#animation-cost").textContent = `${sequential ? Math.max(1, count - 1) : count} tokens`; const note = root.querySelector(".animation-cost span"); if (note) note.textContent = sequential ? "The source is reused; GPT Image edits each additional frame in sequence. One automatic correction may consume one extra token." : "One pose-plan call plus one identity-locked render for every generated frame."; };
